/* Hidden elements protection */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #231b38;
  --color-card: #382c54;
  --color-card-inner: #4b3d6d;
  --color-accent: #f7a239;
  --color-accent-hover: #ffb85c;
  --color-accent-active: #de8723;
  --color-text: #f5f3ff;
  --color-muted: #c2bbe0;
  --color-border: #181228;
  --color-success: #67d686;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 24px 16px;
}

.shelter-card {
  background-color: var(--color-card);
  border: 4px solid var(--color-border);
  box-shadow: 8px 8px 0px var(--color-border);
  width: 100%;
  max-width: 760px;
  padding: 24px;
  border-radius: 4px;
}

.shelter-header {
  text-align: center;
  margin-bottom: 24px;
}

.pixel-icon-shelter {
  width: 10px;
  height: 10px;
  margin: 0 auto 12px;
  box-shadow:
    -10px 0 0 var(--color-accent),
    0 -10px 0 var(--color-accent),
    10px 0 0 var(--color-accent),
    -20px 10px 0 var(--color-accent),
    -10px 10px 0 var(--color-accent),
    0 10px 0 var(--color-accent),
    10px 10px 0 var(--color-accent),
    20px 10px 0 var(--color-accent),
    -20px 20px 0 var(--color-accent),
    20px 20px 0 var(--color-accent);
}

h1 {
  font-size: 26px;
  font-weight: 800;
  letter-spacing: 0.5px;
  color: var(--color-accent);
  margin-bottom: 6px;
  text-transform: uppercase;
}

.subtitle {
  color: var(--color-muted);
  font-size: 16px;
}

.counter-panel {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.counter-badge {
  background-color: var(--color-card-inner);
  border: 2px solid var(--color-border);
  padding: 10px 18px;
  display: flex;
  align-items: center;
  gap: 8px;
  box-shadow: 4px 4px 0px var(--color-border);
}

.counter-label {
  font-weight: 600;
  color: var(--color-muted);
}

.counter-value {
  font-size: 20px;
  color: var(--color-accent);
  min-width: 20px;
  text-align: center;
}

.filter-section {
  margin-bottom: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.filter-title {
  font-weight: 700;
  font-size: 16px;
  color: var(--color-muted);
}

.filter-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
}

.btn {
  font-family: inherit;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  border: 2px solid var(--color-border);
  background-color: var(--color-card-inner);
  color: var(--color-text);
  padding: 8px 16px;
  box-shadow: 3px 3px 0px var(--color-border);
  transition: transform 0.05s ease, background-color 0.1s ease;
}

.btn:hover {
  background-color: var(--color-accent-hover);
  color: #181228;
}

.btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px var(--color-border);
}

.btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.filter-btn.active {
  background-color: var(--color-accent);
  color: #181228;
}

.pets-section {
  margin-bottom: 24px;
}

.section-title {
  font-size: 20px;
  font-weight: 700;
  border-bottom: 2px solid var(--color-border);
  padding-bottom: 8px;
  margin-bottom: 16px;
}

.pet-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));
  gap: 16px;
}

.pet-card {
  background-color: var(--color-card-inner);
  border: 3px solid var(--color-border);
  padding: 16px;
  box-shadow: 4px 4px 0px var(--color-border);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.pet-card.adopted {
  opacity: 0.9;
  border-color: var(--color-success);
}

.avatar-container {
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
  background-color: var(--color-card);
  border: 2px solid var(--color-border);
}

/* Pixel Art via Box Shadows (4px grid) */
.pixel-pet {
  width: 4px;
  height: 4px;
}

.pixel-cat {
  box-shadow:
    -8px -8px 0 #ff9955, 8px -8px 0 #ff9955,
    -8px -4px 0 #ff9955, -4px -4px 0 #ff9955, 0px -4px 0 #ff9955, 4px -4px 0 #ff9955, 8px -4px 0 #ff9955,
    -8px 0 0 #ff9955, -4px 0 0 #181228, 0 0 0 #ff9955, 4px 0 0 #181228, 8px 0 0 #ff9955,
    -8px 4px 0 #ff9955, -4px 4px 0 #ff9955, 0 4px 0 #ff6688, 4px 4px 0 #ff9955, 8px 4px 0 #ff9955,
    -4px 8px 0 #ff9955, 0 8px 0 #ff9955, 4px 8px 0 #ff9955;
}

.pixel-dog {
  box-shadow:
    -12px -4px 0 #8b5a2b, 12px -4px 0 #8b5a2b,
    -8px -4px 0 #d2a679, -4px -4px 0 #d2a679, 0 -4px 0 #d2a679, 4px -4px 0 #d2a679, 8px -4px 0 #d2a679,
    -12px 0 0 #8b5a2b, -8px 0 0 #d2a679, -4px 0 0 #181228, 0 0 0 #d2a679, 4px 0 0 #181228, 8px 0 0 #d2a679, 12px 0 0 #8b5a2b,
    -8px 4px 0 #d2a679, -4px 4px 0 #d2a679, 0 4px 0 #181228, 4px 4px 0 #d2a679, 8px 4px 0 #d2a679,
    -4px 8px 0 #d2a679, 0 8px 0 #e67e22, 4px 8px 0 #d2a679;
}

.pixel-bunny {
  box-shadow:
    -8px -12px 0 #f0e6ff, 8px -12px 0 #f0e6ff,
    -8px -8px 0 #ff99bb, 8px -8px 0 #ff99bb,
    -8px -4px 0 #f0e6ff, -4px -4px 0 #f0e6ff, 0 -4px 0 #f0e6ff, 4px -4px 0 #f0e6ff, 8px -4px 0 #f0e6ff,
    -8px 0 0 #f0e6ff, -4px 0 0 #e83e8c, 0 0 0 #f0e6ff, 4px 0 0 #e83e8c, 8px 0 0 #f0e6ff,
    -8px 4px 0 #f0e6ff, -4px 4px 0 #f0e6ff, 0 4px 0 #ff99bb, 4px 4px 0 #f0e6ff, 8px 4px 0 #f0e6ff,
    -4px 8px 0 #f0e6ff, 0 8px 0 #f0e6ff, 4px 8px 0 #f0e6ff;
}

.pet-name {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 4px;
}

.pet-meta {
  font-size: 16px;
  color: var(--color-muted);
  margin-bottom: 12px;
}

.btn-adopt {
  width: 100%;
  background-color: var(--color-accent);
  color: #181228;
  margin-top: auto;
}

.btn-adopt:hover {
  background-color: var(--color-accent-hover);
}

.btn-adopt:active {
  background-color: var(--color-accent-active);
}

.adopted-badge {
  display: inline-block;
  background-color: var(--color-border);
  color: var(--color-success);
  font-weight: 700;
  font-size: 16px;
  padding: 6px 12px;
  border: 1px solid var(--color-success);
  margin-top: auto;
}

.empty-msg {
  font-style: italic;
  color: var(--color-muted);
  text-align: center;
  padding: 24px;
  background-color: var(--color-card-inner);
  border: 2px dashed var(--color-border);
}

@media (max-width: 480px) {
  body {
    padding: 12px 8px;
  }

  .shelter-card {
    padding: 16px;
  }

  .pet-grid {
    grid-template-columns: 1fr;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const pets = [
    { id: 1, name: 'Mochi', species: 'Cat', age: '2 yrs', adopted: false },
    { id: 2, name: 'Rusty', species: 'Dog', age: '3 yrs', adopted: false },
    { id: 3, name: 'Clover', species: 'Bunny', age: '1 yr', adopted: false },
    { id: 4, name: 'Luna', species: 'Cat', age: '4 yrs', adopted: false },
    { id: 5, name: 'Barnaby', species: 'Dog', age: '1 yr', adopted: false },
    { id: 6, name: 'Pippin', species: 'Bunny', age: '2 yrs', adopted: false }
  ];

  let currentFilter = 'All';

  const availableListEl = document.getElementById('available-list');
  const adoptedListEl = document.getElementById('adopted-list');
  const availableCountEl = document.getElementById('available-count');
  const adoptedCountEl = document.getElementById('adopted-count');
  const emptyAvailableMsg = document.getElementById('empty-available-msg');
  const emptyAdoptedMsg = document.getElementById('empty-adopted-msg');
  const filterButtons = document.querySelectorAll('.filter-btn');

  function getPixelClass(species) {
    switch (species.toLowerCase()) {
      case 'cat': return 'pixel-cat';
      case 'dog': return 'pixel-dog';
      case 'bunny': return 'pixel-bunny';
      default: return '';
    }
  }

  function createPetCard(pet) {
    const card = document.createElement('article');
    card.className = `pet-card ${pet.adopted ? 'adopted' : ''}`;
    card.setAttribute('role', 'listitem');
    card.setAttribute('aria-label', `${pet.name}, a ${pet.age} old ${pet.species}`);

    const avatar = document.createElement('div');
    avatar.className = 'avatar-container';
    avatar.setAttribute('aria-hidden', 'true');
    const pixelArt = document.createElement('div');
    pixelArt.className = `pixel-pet ${getPixelClass(pet.species)}`;
    avatar.appendChild(pixelArt);

    const nameEl = document.createElement('h3');
    nameEl.className = 'pet-name';
    nameEl.textContent = pet.name;

    const metaEl = document.createElement('p');
    metaEl.className = 'pet-meta';
    metaEl.textContent = `${pet.species} • ${pet.age}`;

    card.appendChild(avatar);
    card.appendChild(nameEl);
    card.appendChild(metaEl);

    if (!pet.adopted) {
      const adoptBtn = document.createElement('button');
      adoptBtn.type = 'button';
      adoptBtn.className = 'btn btn-adopt';
      adoptBtn.textContent = 'Adopt';
      adoptBtn.setAttribute('aria-label', `Adopt ${pet.name}`);
      adoptBtn.addEventListener('click', () => adoptPet(pet.id));
      card.appendChild(adoptBtn);
    } else {
      const adoptedBadge = document.createElement('span');
      adoptedBadge.className = 'adopted-badge';
      adoptedBadge.textContent = '✓ Adopted';
      card.appendChild(adoptedBadge);
    }

    return card;
  }

  function adoptPet(petId) {
    const pet = pets.find(p => p.id === petId);
    if (pet && !pet.adopted) {
      pet.adopted = true;
      render();
    }
  }

  function render() {
    const availablePets = pets.filter(p => !p.adopted);
    const adoptedPets = pets.filter(p => p.adopted);

    availableCountEl.textContent = availablePets.length;
    adoptedCountEl.textContent = adoptedPets.length;

    const filteredAvailable = availablePets.filter(p => {
      return currentFilter === 'All' || p.species.toLowerCase() === currentFilter.toLowerCase();
    });

    availableListEl.textContent = '';
    if (filteredAvailable.length === 0) {
      emptyAvailableMsg.hidden = false;
    } else {
      emptyAvailableMsg.hidden = true;
      filteredAvailable.forEach(pet => {
        availableListEl.appendChild(createPetCard(pet));
      });
    }

    adoptedListEl.textContent = '';
    if (adoptedPets.length === 0) {
      emptyAdoptedMsg.hidden = false;
    } else {
      emptyAdoptedMsg.hidden = true;
      adoptedPets.forEach(pet => {
        adoptedListEl.appendChild(createPetCard(pet));
      });
    }
  }

  filterButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      filterButtons.forEach(b => {
        b.classList.remove('active');
        b.setAttribute('aria-pressed', 'false');
      });
      btn.classList.add('active');
      btn.setAttribute('aria-pressed', 'true');
      currentFilter = btn.getAttribute('data-species');
      render();
    });
  });

  render();
});
